<template>
  <SafetyManagementShell title="每日安全生产检查记录" subtitle="七类检查汇总 · 每天一份 · 三类人员签认方式待定">
    <view class="sm-stack">
      <view class="sm-card"><view class="sm-section-head"><view class="sm-row"><text class="sm-h2">日管控</text><picker mode="date" :value="selectedDate" @change="changeDate($event.detail.value)"><view class="sm-picker">{{ selectedDate }} ▾</view></picker></view><text class="sm-tag sm-tag--warn">待签认</text></view><text class="sm-help">日期按北京时间、实际巡查完成日归属。多次巡查分别保留时段，后一次正常不覆盖前一次问题。</text></view>
      <view v-if="loading" class="sm-state">正在汇总当天全部原记录…</view>
      <view v-else-if="error" class="sm-alert sm-alert--error">{{ error }}<button class="sm-btn sm-btn--secondary" @click="load">重新加载</button></view>
      <template v-else>
        <view v-if="editingConflict" class="sm-alert sm-alert--error">补充记录已被其他操作更新。当前编辑基于版本 {{ editRevision }}，服务器为版本 {{ supplementRevision }}；请先保留当前文字，再重新加载后合并，系统不会覆盖新版。<button class="sm-btn sm-btn--secondary sm-btn--small" @click="reloadEditing">重新加载补充</button></view>
        <view v-if="daily.stale" class="sm-alert">当天新增巡检、补充或关联资料已有变化。原核对版本保留，请检查变化后重新核对。</view>
        <view v-if="!permissions.daily" class="sm-alert sm-alert--info">当前账号可查看材料；填写补充检查及核对日表须配置为本厂站安全员。</view>
        <view class="sm-tabs"><view v-for="tab in tabs" :key="tab.key" :class="['sm-tab',{'sm-tab--active':activeTab===tab.key}]" @click="activeTab=tab.key">{{ tab.label }}</view></view>
        <view v-show="activeTab==='sources'" class="sm-stack">
          <view class="sm-card"><view class="sm-section-head"><text class="sm-h2">当天巡检 · {{ snapshot.inspections?.length || 0 }} 次</text><button class="sm-btn sm-btn--secondary sm-btn--small" @click="openPage('/pages/station-safety-inspection/form')">新增巡检</button></view><text v-if="!snapshot.inspections?.length" class="sm-alert">尚无当天巡检记录。补充可以暂存，日表不能据此认定完整。</text><view v-for="inspection in snapshot.inspections" :key="inspection._id" class="sm-list-row"><view class="sm-section-head"><text class="sm-h3">{{ inspection.inspection_no }}</text><text class="sm-link" @click="openInspection(inspection._id)">查看原单及照片</text></view><text class="sm-text">{{ inspection.inspector_name }} · {{ inspection.weather || '天气未记录' }}</text><text class="sm-help">实际巡查：{{ formatDateTime(inspection.started_at) }} 至 {{ formatDateTime(inspection.ended_at) }}</text><text class="sm-help">系统提交：{{ formatDateTime(inspection.submitted_at || inspection.created_at) }} · 原单版本 {{ inspection.revision || 1 }} · {{ inspection.abnormal_count || 0 }} 项异常</text></view></view>
          <view v-for="category in snapshot.categories" :key="category.id" class="sm-card"><view class="sm-section-head"><text class="sm-h2">{{ category.id }}．{{ category.name }}</text><text class="sm-tag">{{ category.checks?.length || 0 }} 条引用</text></view><view v-for="(check,index) in category.checks" :key="`${check.source_id}-${check.item_code}-${index}`" class="sm-list-row"><view class="sm-row"><text :class="['sm-tag',check.result_code==='abnormal'?'sm-tag--bad':check.result_code==='normal'?'sm-tag--good':'sm-tag--warn']">{{ resultLabels[check.result_code] || '待完成' }}</text><text class="sm-h3">{{ check.label }}</text></view><text v-if="check.note" class="sm-text">{{ check.note }}</text><text class="sm-help">{{ check.source_type==='supplement'?'补充检查':'原巡检' }} · {{ check.item_code }}<template v-if="check.related_categories?.length"> · 同一证据同时支持第 {{ check.related_categories.join('、') }} 类</template></text><text v-if="check.hazard_ids?.length" class="sm-help">关联隐患：{{ check.hazard_ids.join('、') }}</text></view><text v-if="!category.checks?.length" class="sm-help">尚无检查事实引用，不能自动判为正常。</text></view>
        </view>
        <view v-show="activeTab==='supplement'" class="sm-stack">
          <view class="sm-alert sm-alert--info">补充检查可分次暂存和续填。未填保持待完成；无充装、无特殊作业不取消静态设施检查，吊秤及防脱钩仍由原巡检检查。</view>
          <template v-for="definition in definitions" :key="definition.code"><view v-if="definition.code==='S13a'" class="sm-card"><text class="sm-h2">S13 · 当日卸车、装卸作业</text><text class="sm-help">当天实际开展装卸时，展开设备、人员过程及天气工况三项检查；无作业只需填写一次事实说明。</text><view class="sm-options sm-field"><view :class="['sm-option',{'sm-option--active':unloadingChoice==='conducted'}]" @click="chooseUnloading(true)">当日开展，逐项核对</view><view :class="['sm-option',{'sm-option--active':unloadingChoice==='not_conducted'}]" @click="chooseUnloading(false)">当日未开展</view></view><label v-if="unloadingChoice==='not_conducted'" class="sm-field"><text class="sm-field-label">未开展说明 *</text><textarea v-model="unloadingReason" class="sm-textarea" :disabled="!permissions.daily" placeholder="填写当天无卸车、装卸作业的实际情况" /></label><text v-if="!unloadingChoice" class="sm-help">尚未确认当天是否开展装卸作业。</text></view><view v-if="!definition.code.startsWith('S13') || unloadingChoice==='conducted'" class="sm-card"><view class="sm-section-head"><text class="sm-h2">{{ definition.code }} · {{ definition.label }}</text><text class="sm-tag">第 {{ definition.category_code }} 类</text></view><text class="sm-help">{{ definition.standard }}</text>
            <view class="sm-field"><text class="sm-field-label">检查结果</text><view class="sm-options"><view v-for="result in definition.allowed_results" :key="result" :class="['sm-option',{'sm-option--active':itemFor(definition.code).result_code===result,'sm-option--abnormal':result==='abnormal'}]" @click="setResult(definition.code,result)">{{ resultLabels[result] }}</view></view><text v-if="!itemFor(definition.code).result_code" class="sm-help">待填写</text></view>
            <label v-if="['not_conducted','not_running','not_applicable'].includes(itemFor(definition.code).result_code)" class="sm-field"><text class="sm-field-label">事实说明 / 适用原因 *</text><textarea v-model="itemFor(definition.code).reason" class="sm-textarea" :disabled="!permissions.daily" maxlength="1000" placeholder="说明当天未开展、未运行或不适用的实际情况" /></label>
            <label class="sm-field"><text class="sm-field-label">{{ itemFor(definition.code).result_code==='abnormal'?'本次具体问题 *':'检查说明 / 变化情况' }}</text><textarea v-model="itemFor(definition.code).note" class="sm-textarea" :disabled="!permissions.daily" maxlength="2000" placeholder="可注明已引用的原检查内容，只补未覆盖或发生变化的部分" /></label>
            <template v-if="definition.code==='S01' && ['normal','abnormal'].includes(itemFor('S01').result_code)"><view class="sm-grid"><label class="sm-field"><text class="sm-field-label">实际作业类型</text><input v-model="itemFor('S01').details.types" class="sm-input" :disabled="!permissions.daily" placeholder="动火、有限空间、高处、吊装、临时用电等" /></label><label class="sm-field"><text class="sm-field-label">作业地点 *</text><input v-model="itemFor('S01').details.location" class="sm-input" :disabled="!permissions.daily" /></label></view><label v-for="field in specialFields" :key="field.key" class="sm-field"><text class="sm-field-label">{{ field.label }} *</text><textarea v-model="itemFor('S01').details[field.key]" class="sm-textarea" :disabled="!permissions.daily" /></label></template>
            <SafetyEvidenceEditor v-model="itemFor(definition.code).evidence" :readonly="!permissions.daily" @busy="setUploading(definition.code,$event)" />
            <view v-if="itemFor(definition.code).hazard_ids.length" class="sm-alert sm-alert--info">已关联隐患：{{ itemFor(definition.code).hazard_ids.join('、') }}。本次复见记录与原隐患共用编号。</view>
            <button v-if="permissions.daily && activeIssue!==definition.code" class="sm-btn sm-btn--secondary sm-btn--small" @click="openIssue(definition.code)">登记问题 / 关联未关闭隐患</button>
            <SafetyIssueEditor v-if="activeIssue===definition.code" :date="selectedDate" :source-item-code="definition.code" :category="Number(definition.category_code)" :hazards="availableHazards" :initial-note="itemFor(definition.code).note" :evidence="itemFor(definition.code).evidence" @saved="issueSaved(definition.code,$event)" @cancel="activeIssue=''" />
          </view></template>
          <view v-if="permissions.daily" class="sm-card"><label class="sm-field"><text class="sm-field-label">{{ supplementRevision ? '补充记录修订原因 / 本次变化说明' : '补充记录说明' }}</text><textarea v-model="supplementReason" class="sm-textarea" placeholder="记录后续巡检的新情况、修正依据或暂存说明" /></label><button class="sm-btn" :disabled="saving" @click="saveSupplement">{{ saving?'保存中…':'暂存补充检查' }}</button><text class="sm-help">当前补充版本 {{ supplementRevision }}。保存补充不修改原巡检记录。</text></view>
        </view>
        <view v-show="activeTab==='issues'" class="sm-stack"><view class="sm-card"><view class="sm-section-head"><text class="sm-h2">当天全部问题 · {{ snapshot.issues?.length || 0 }} 项</text><text class="sm-link" @click="openHazards">进入整改台账</text></view><text class="sm-help">按唯一隐患编号展示。复见关联同一问题，当天已整改和已关闭的问题仍保留。</text><view v-for="issue in snapshot.issues" :key="issue._id" class="sm-list-row"><text class="sm-h3">{{ issue.hazard_no || issue._id }} · {{ issue.hazard_level==='major'?'重大':'一般' }}</text><text class="sm-text">{{ issue.issue_note }}</text><text class="sm-help">责任人：{{ issue.responsible_name || '未填写' }} · 期限：{{ issue.planned_complete_date || '未填写' }} · {{ hazardStatus(issue.status) }}</text><text class="sm-text">整改要求：{{ issue.planned_measure || '未填写' }}</text></view><text v-if="!snapshot.issues?.length" class="sm-help">当前材料未发现当天问题；是否可以零报告仍需全部检查完成后核对。</text></view>
          <view class="sm-card"><text class="sm-h2">本次观察、上报与当场整改</text><view v-for="observation in snapshot.observations" :key="observation._id" class="sm-list-row"><text class="sm-h3">{{ observation.hazard_id }}</text><text class="sm-text">{{ observation.issue_note || observation.note }}</text><text class="sm-help">{{ formatDateTime(observation.discovered_at || observation.observed_at) }} · 临时措施：{{ observation.temporary_controls || '未记录' }}</text><text v-if="observation.report?.reported_at" class="sm-text">实际上报：{{ formatDateTime(observation.report.reported_at) }}，{{ observation.report.reported_to }}，{{ observation.report.method }}；{{ observation.report.requirements }}</text><text v-if="observation.on_site_rectification?.note" class="sm-text">当场整改：{{ observation.on_site_rectification.note }}；{{ formatDateTime(observation.on_site_rectification.completed_at) }}；复查：{{ observation.on_site_rectification.recheck_note }}</text></view><text v-if="!snapshot.observations?.length" class="sm-help">暂无另行登记的观察记录。</text></view>
          <view class="sm-card"><text class="sm-h2">历史待办 · {{ snapshot.historical_pending?.length || 0 }} 项</text><text class="sm-help">历史待办与当日新发现分别展示。仍存在未解决问题时不能确认零报告。</text><view v-for="issue in snapshot.historical_pending" :key="issue._id" class="sm-list-row"><text class="sm-h3">{{ issue.hazard_no || issue._id }}</text><text class="sm-text">{{ issue.issue_note }}</text><text class="sm-help">{{ issue.responsible_name }} · {{ issue.planned_complete_date }} · 截至 {{ issue.as_of_date || selectedDate }}：{{ hazardStatus(issue.status) }}<template v-if="issue.current_status"> · 当前：{{ hazardStatus(issue.current_status) }}</template><template v-if="issue.closure_time_unverified"> · 关闭时间证据待核验</template></text></view></view>
        </view>
        <view v-show="activeTab==='review'" class="sm-stack">
          <view v-if="hasUnsavedChanges" class="sm-alert">有尚未保存的补充编辑，请先暂存，再核对日表。当前完整性依据已保存资料。</view><view class="sm-card"><text class="sm-h2">内容完整性</text><text v-if="snapshot.complete" class="sm-alert sm-alert--info">当前检查与补充内容齐全，可核对形成日表。</text><view v-else class="sm-alert"><text class="sm-text">待完成事项</text><text v-for="(missing,index) in snapshot.missing" :key="index" class="sm-text">• {{ missing }}</text></view><text class="sm-help">核对的是事实内容，签认状态始终为“待签认”。</text></view>
          <view class="sm-card"><text class="sm-h2">零报告确认</text><view class="sm-options sm-field"><view :class="['sm-option',{'sm-option--active':zeroReport===false}]" @click="zeroReport=false">不确认零报告</view><view :class="['sm-option',{'sm-option--active':zeroReport===true}]" @click="zeroReport=true">实际未发现问题，确认零报告</view></view><text class="sm-help">当天发现过问题、仍有历史未解决隐患或检查不完整时，服务端不允许确认零报告。</text></view>
          <view class="sm-card"><text class="sm-h2">台账核对与修订</text><text class="sm-text">{{ daily.record ? `已有核对版本 ${daily.record.revision} · ${formatDateTime(daily.record.checked_at)}` : '尚未形成已核对版本' }} · 待签认</text><text v-if="daily.record?.revision_reason" class="sm-help">上版说明：{{ daily.record.revision_reason }}</text><label class="sm-field"><text class="sm-field-label">{{ daily.record ? '本次修订原因 *' : '核对说明' }}</text><textarea v-model="revisionReason" class="sm-textarea" :disabled="!permissions.daily" placeholder="修订需写明新增、变更或更正的依据" /></label><button v-if="permissions.daily" class="sm-btn" :disabled="saving || !snapshot.complete || hasUnsavedChanges || editingConflict" @click="confirm">{{ saving?'保存中…':daily.record?'形成修订版并核对':'核对日表内容' }}</button><text class="sm-help">未保存的补充请先暂存。新增或更正来源后，日表会重新标记待核对，旧版保留。</text></view>
        </view>
        <SafetyRevisionHistory kind="daily" :record-id="daily.record?._id" title="日表修订历史" /><SafetyRevisionHistory kind="supplement" :record-id="daily.supplement?._id" title="补充检查修订历史" />
        <view class="sm-card sm-row"><button class="sm-btn sm-btn--secondary" @click="openSafetyPage('print',{kind:'daily',date:selectedDate})">打印预览 / 保存 PDF</button><button v-if="permissions.export" class="sm-btn sm-btn--secondary" :disabled="exporting" @click="exportExcel">{{ exporting?'正在生成…':'导出 Excel 明细' }}</button><button class="sm-btn sm-btn--secondary" @click="refreshSummary">刷新来源</button><text class="sm-help">打印和导出使用已保存资料；未保存的编辑不包含在导出中。</text></view>
      </template>
    </view>
  </SafetyManagementShell>
</template>
<script setup>
import { computed,onMounted,ref,watch } from 'vue'
import SafetyManagementShell from './SafetyManagementShell.vue'
import SafetyEvidenceEditor from './SafetyEvidenceEditor.vue'
import SafetyIssueEditor from './SafetyIssueEditor.vue'
import SafetyRevisionHistory from './SafetyRevisionHistory.vue'
import { getSafetyConfig,getSafetyDaily,saveSafetySupplement,confirmSafetyDaily,exportSafetyDocument } from '@/services/safetyManagement'
import { beijingDate,clone,downloadFile,formatDateTime,openSafetyPage,openPage,openInspection,openHazards,resultLabels,showError } from './helpers'
const props=defineProps({date:{type:String,default:''}})
const selectedDate=ref(props.date || beijingDate()),loading=ref(true),saving=ref(false),exporting=ref(false),error=ref(''),daily=ref({}),definitions=ref([]),items=ref([]),activeTab=ref('supplement'),activeIssue=ref(''),supplementReason=ref(''),revisionReason=ref(''),zeroReport=ref(false),editRevision=ref(0),editBaseline=ref(''),uploadingItems=ref(new Set()),unloadingActive=ref(false)
const tabs=[{key:'supplement',label:'补充检查'},{key:'sources',label:'七类检查与原单'},{key:'issues',label:'问题与历史待办'},{key:'review',label:'核对日表'}]
const specialFields=[{key:'approval',label:'审批及作业票核对'},{key:'monitor',label:'实际监护安排'},{key:'measures',label:'现场安全措施核对'}]
const snapshot=computed(()=>daily.value.snapshot || {}),permissions=computed(()=>daily.value.permissions || {}),supplementRevision=computed(()=>daily.value.supplement?.revision || 0)
const hasUnsavedChanges=computed(()=>JSON.stringify(items.value)!==editBaseline.value),editingConflict=computed(()=>supplementRevision.value!==editRevision.value)
const availableHazards=computed(()=>[...new Map([...(snapshot.value.issues || []),...(snapshot.value.historical_pending || [])].map(item=>[item._id,item])).values()])
function itemFor(code){return items.value.find(item=>item.code===code)}
const unloadingCodes=['S13a','S13b','S13c']
const unloadingChoice=computed(()=>unloadingActive.value?'conducted':unloadingCodes.every(code=>itemFor(code)?.result_code==='not_conducted')?'not_conducted':'')
const unloadingReason=computed({get:()=>itemFor('S13a')?.reason || '',set:value=>{for(const code of unloadingCodes){const item=itemFor(code);if(item)item.reason=value}}})
function chooseUnloading(conducted){if(!permissions.value.daily)return;unloadingActive.value=conducted;for(const code of unloadingCodes){const item=itemFor(code);if(!item)continue;if(conducted && item.result_code==='not_conducted'){item.result_code='';item.reason=''}else if(!conducted)item.result_code='not_conducted'}}
function hydrateItems(stored=[]){items.value=definitions.value.map(def=>({code:def.code,result_code:'',note:'',reason:'',evidence:[],hazard_ids:[],details:{types:'',location:'',approval:'',monitor:'',measures:''},...clone(stored.find(item=>item.code===def.code) || {}),details:{types:'',location:'',approval:'',monitor:'',measures:'',...(stored.find(item=>item.code===def.code)?.details || {})}}));editBaseline.value=JSON.stringify(items.value);unloadingActive.value=unloadingCodes.some(code=>{const result=itemFor(code)?.result_code;return result && result!=='not_conducted'})}
function setUploading(code,busy){if(busy)uploadingItems.value.add(code);else uploadingItems.value.delete(code)}
function setResult(code,result){if(permissions.value.daily)itemFor(code).result_code=result}
function openIssue(code){itemFor(code).result_code='abnormal';activeIssue.value=code}
function hazardStatus(value){return({pending_rectification:'待整改',pending_verification:'待复查',closed:'已复查销号',cancelled:'已取消'})[value] || value}
async function load(){loading.value=true;error.value='';try{const [config,result]=await Promise.all([getSafetyConfig(),getSafetyDaily({date:selectedDate.value})]);definitions.value=config.supplement_definitions || [];daily.value=result;hydrateItems(result.supplement?.items || []);editRevision.value=result.supplement?.revision || 0;zeroReport.value=Boolean(result.record?.zero_report)}catch(err){error.value=err.message}finally{loading.value=false}}
async function refreshSummary(){try{daily.value=await getSafetyDaily({date:selectedDate.value})}catch(err){showError(err)}}
async function persistSupplement(){if(uploadingItems.value.size)throw new Error('照片正在上传，请完成后再保存补充');const saved=await saveSafetySupplement({date:selectedDate.value,expected_revision:editRevision.value,revision_reason:supplementReason.value,items:items.value});editRevision.value=saved.revision;hydrateItems(saved.items || items.value);daily.value=await getSafetyDaily({date:selectedDate.value});supplementReason.value=''}
function reloadEditing(){uni.showModal({title:'重新加载补充',content:'当前未保存的编辑将被服务器版本替换，请先保留需要合并的文字。',success:result=>{if(result.confirm){hydrateItems(daily.value.supplement?.items || []);editRevision.value=supplementRevision.value}}})}
async function saveSupplement(){saving.value=true;try{await persistSupplement();uni.showToast({title:'补充已暂存',icon:'success'})}catch(err){showError(err)}finally{saving.value=false}}
async function issueSaved(code,result){const item=itemFor(code);item.hazard_ids=[...new Set([...item.hazard_ids,result.hazard_id])];activeIssue.value='';supplementReason.value=supplementReason.value || '新增问题或记录本次复见';try{await persistSupplement()}catch(err){showError(new Error(`隐患已登记，补充关联尚未保存：${err.message}`))}}
async function confirm(){if(hasUnsavedChanges.value||editingConflict.value){showError(new Error('请先保存补充，或重新加载并合并版本冲突'));return}saving.value=true;try{await confirmSafetyDaily({date:selectedDate.value,expected_revision:daily.value.record?.revision || 0,source_fingerprint:snapshot.value.source_fingerprint,zero_report:zeroReport.value,revision_reason:revisionReason.value});revisionReason.value='';await refreshSummary();uni.showToast({title:'内容已核对，待签认',icon:'none'})}catch(err){showError(err)}finally{saving.value=false}}
async function exportExcel(){exporting.value=true;try{downloadFile(await exportSafetyDocument({kind:'daily',date:selectedDate.value,format:'xlsx'}))}catch(err){showError(err)}finally{exporting.value=false}}
async function changeDate(date){if(date===selectedDate.value)return;uni.showModal({title:'切换日期',content:'请先保存当前补充。切换后未保存的编辑将不保留。',success:async result=>{if(result.confirm){selectedDate.value=date;activeIssue.value='';supplementReason.value='';revisionReason.value='';await load()}}})}
watch(()=>props.date,date=>{if(date&&date!==selectedDate.value){selectedDate.value=date;load()}})
onMounted(load)
</script>
